const cameras = $input.all().map(i => i.json);
const cfg = $('Config').first().json;
const counts = { 'Pendente':0, 'Aguardando resposta':0, 'Verificando':0, 'Suporte':0, 'Aguardando validacao':0, 'Resolvido':0 };
for (const c of cameras) { const st = String(c.status || '').trim(); if (counts[st] !== undefined) counts[st]++; }
const today = new Date().toISOString().slice(0,10);
const resolvidasHoje = cameras.filter(c => String(c.data_resolucao || '').slice(0,10) === today).length;
const payload = { messaging_product: 'whatsapp', to: cfg.gestorTelefone, type: 'template', template: { name: 'resumo_diario', language: { code: 'pt_BR' }, components: [ { type: 'body', parameters: [ { type: 'text', text: String(counts['Pendente']) }, { type: 'text', text: String(counts['Aguardando resposta']) }, { type: 'text', text: String(counts['Verificando']) }, { type: 'text', text: String(counts['Suporte']) }, { type: 'text', text: String(resolvidasHoje) } ] } ] } };
return [{ json: { gestor: cfg.gestorTelefone, counts: counts, resolvidasHoje: resolvidasHoje, payload: payload } }];
